package com.cpf.testkit; import com.cpf.core.api.transaction.CpfTransactionIdGenerator; import com.cpf.core.api.transaction.CpfTransactionIds; import java.util.concurrent.atomic.AtomicLong; public final class CpfDeterministicTransactionIdGenerator implements CpfTransactionIdGenerator { private final String system; private final String instanceToken; private final String prefix; private final AtomicLong seq=new AtomicLong(); public CpfDeterministicTransactionIdGenerator(String prefix17,String system3,String instanceToken7){this.prefix=prefix17;this.system=system3;this.instanceToken=instanceToken7;} public String generate(){return CpfTransactionIds.requireCanonical(prefix+system+instanceToken+String.format("%07d",seq.incrementAndGet()%10_000_000));} public String generateOrUse(String incoming){return CpfTransactionIds.isCanonical(incoming)?incoming:generate();} public boolean isValid(String v){return CpfTransactionIds.isCanonical(v);} public String getModuleId(){return system;} public String getInstanceToken(){return instanceToken;} }
